import {useMemo} from 'react';
import {Assignee} from '../../../../model/interface/dashboard.interface';
import TableCM from '../../../components/Table';
import {Image, ScrollView, Text, View} from 'react-native';
import {Font, String} from '../../../../constants';
import TextCM from '../../../components/Text';
import {SafeAreaView} from 'react-native-safe-area-context';
import {styles} from './styles';

type Props = {
  asignee: Assignee[];
};
const DashboardAsignee = ({asignee}: Props) => {
  const dataTable = useMemo(() => {
    return asignee
      .sort((a, b) => b.taskCount - a.taskCount)
      .map((item, index) => {
        return {
          STT: index,
          'HM.Asignee': (
            <View style={styles.container} key={index}>
              <View style={styles.avatarContainer}>
                <Image
                  width={32}
                  height={32}
                  borderRadius={25}
                  source={{
                    uri: item.avatar || String.DEFAULT_IMAGE,
                  }}
                />
              </View>
              <View style={styles.infoContainer}>
                <TextCM style={styles.username}>{item.name}</TextCM>
                <TextCM style={styles.email}>{item.email}</TextCM>
              </View>
            </View>
          ),
          Quantity: item.taskCount || 0,
        };
      });
  }, [asignee]);
  return (
    <SafeAreaView edges={['bottom']} style={{flex: 1}}>
      <TextCM
        style={styles.txtTitle}>
        {'Số lượng task theo assignee'}
      </TextCM>
      <ScrollView style={{flex: 1}} showsVerticalScrollIndicator={false}>
        <TableCM
          styleTextHeader={{
            fontFamily: Font.InterSemiBold600,
            color: 'rgba(0, 32, 77, .9)',
          }}
          styleHeader={{
            backgroundColor: '#f1f1f1',
          }}
          tableHeaders={['HM.Asignee', 'HM.Quantity']}
          tableData={dataTable}
        />
      </ScrollView>
    </SafeAreaView>
  );
};

export default DashboardAsignee;
