import {
  FlatList,
  Pressable,
  RefreshControl,
  useWindowDimensions,
  View,
  TextInput,
  ScrollView,
  Text,
  TouchableOpacity,
} from 'react-native';
import {GroupTaskList, ITask} from '../../../board/store/interface';
import TextCM from '../../../../components/Text';
import {
  Dispatch,
  SetStateAction,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {IATTR} from '../../helper';
import {
  useBoardService,
  useTaskService,
  useUserService,
} from '../../../../../hooks/apiHooks/useAPI';
import {
  AssignGroupList,
  AssignOrgList,
  AssignTaskList,
  ITaskDetail,
} from './helper';
import {Color, Font, NavigationName} from '../../../../../constants';
import {Icon, ProgressBar} from '@ui-kitten/components';
import DraggableFlatList, {
  ScaleDecorator,
} from 'react-native-draggable-flatlist';
import {GestureHandlerRootView} from 'react-native-gesture-handler';
import ItemTicket from '../item-ticket';
import styles from './styles';
import {
  useFocusEffect,
  useNavigation,
  useRoute,
} from '@react-navigation/native';
import useBoardStore from '../../../board/store';
import ModalFullScreen from '../../../../components/ModalFullScreen';
import AddTaskScreen from './components/add-task';
import {TYPE_SCREEN} from '../../../../../constants/Size';
import {useTranslation} from 'react-i18next';
import Toast from 'react-native-toast-message';
import AddBoard from './components/add-board';
import {KEY_TASK} from '../../../board/helper';
import TableCM from '../../../../components/Table';
import ListTable from './components/list-table/listTable';
import RenderListUserAssign from '../item-ticket/list-assign';
import ModalSelectUser from '../../../../components/ModalSelectUser';
import ModalConfirmCM from '../../../../components/ModalConfirm';
import AuthorityAndShareScreen from '../../../../components/Authority';
import CalenderView from './components/calendar/calendar';

type Props = {
  groupTaskList?: GroupTaskList | undefined;
  taskSelectId: string;
  setGroupTaskList: Dispatch<SetStateAction<GroupTaskList[]>>;
  viewType?: 'table' | 'list' | 'calendar';
};

const TaskDetailItem = ({
  groupTaskList,
  taskSelectId,
  setGroupTaskList,
  viewType,
}: Props) => {
  const {t} = useTranslation();
  const {width} = useWindowDimensions();
  const Taskservices = useTaskService();

  const refInput = useRef<TextInput>(null);
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const attr = useMemo(
    () => groupTaskList?.attr && JSON.parse(groupTaskList.attr),
    [],
  ) as IATTR;
  const UserServices = useUserService();
  const [totalItem, setTotalItem] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [openModal, setOpenModal] = useState<'createTask' | 'editTask' | null>(
    null,
  );
  const [openModalAvatar, setOpenModalAvatar] = useState<
    'assign' | 'tags' | null
  >(null);

  const [page, setPage] = useState(0);
  const [listTask, setListTask] = useState<ITaskDetail[]>([]);
  const [modalDelete, setModalDelete] = useState(false);
  const [selectedTask, setSelectedTask] = useState<ITaskDetail | null>(null);
  const [modalCopy, setModalCopy] = useState(false);
  const [shareAuthorize, setShareAuthorize] = useState(false);
  const BoardServices = useBoardService();
  const {
    setGroupTaskList: setGroupTaskListStore,
    groupTaskList: groupTaskListStore,
    isChangeStatusOfListTask,
    setIsChangeStatusOfListTask,
    keyTaskSelect,
  } = useBoardStore();

  useEffect(() => {
    if (groupTaskList?.id) {
      getTasks(0);
    }
    if (viewType === 'list' || viewType === 'calendar') {
      getAllTasks();
    }
  }, [isChangeStatusOfListTask, viewType, groupTaskList?.id]);

  useFocusEffect(
    useCallback(() => {
      if (route.params?.updatedTask) {
        const updatedTask = route.params.updatedTask as ITaskDetail;
        const taskPrevUpdate = listTask?.find(
          task => task.id === updatedTask.id,
        );

        if (taskPrevUpdate && taskPrevUpdate.status !== updatedTask.status) {
          setIsChangeStatusOfListTask(!isChangeStatusOfListTask);
        } else {
          setListTask(
            listTask.map(task =>
              task.id === updatedTask.id
                ? {
                    ...task,
                    ...updatedTask,
                  }
                : task,
            ),
          );
        }

        // Sau khi dùng xong thì xóa để tránh lặp lại
        navigation.setParams({updatedTask: undefined});
      }
    }, [route.params?.updatedTask]),
  );

  const getTasks = async (page: number) => {
    try {
      const params = {
        page: page,
        size: 50,
        sort: 'createdDate,desc',
      };
      const body = {
        listTaskId: groupTaskList?.listTaskId,
        parentId: 0,
        status: [groupTaskList?.id],
        querySelectTemplate: true,
      };
      const data = await BoardServices.searchTask(
        body,
        params,
        keyTaskSelect === KEY_TASK['assigned-task'],
      );
      if (data) {
        if (page === 0) {
          setListTask(data.data);
        } else {
          setListTask([...listTask, ...data.data]);
        }
        setTotalItem(data?.page?.totalRecords);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };
  const getAllTasks = async () => {
    try {
      const statusList = groupTaskListStore.map(item => item.id); // ✅ lấy toàn bộ id
      const body = {
        listTaskId: taskSelectId,
        parentId: 0,
        status: statusList,
        querySelectTemplate: true,
      };
      const params = {
        page: 0,
        size: 100,
        sort: 'createdDate,desc',
      };
      const data = await BoardServices.searchTask(
        body,
        params,
        keyTaskSelect === KEY_TASK['assigned-task'],
      );
      if (data?.data) {
        setListTask(data.data);
      }
    } catch (e) {
      console.error(e);
    }
  };
  const onRefresh = () => {
    setIsLoading(true);
    setPage(0);
    getTasks(0);
  };

  const fetchNextPage = () => {
    if (listTask?.length < totalItem) {
      setPage(page + 1);
      getTasks(page + 1);
    }
  };

  const handleAddtask = () => {
    setOpenModal('createTask');
  };

  const handleDragData = (task: any[]) => {
    setListTask(task);
  };

  const handleViewDetail = (task: ITaskDetail) => {
    navigation.navigate(NavigationName.TaskDetailScreen, {
      taskId: task.id,
      type: 'task',
    });
  };
  const handleCreateTask = async (data: any) => {
    try {
      const dataUpdate = {
        ...data,
        status: groupTaskList?.id,
        id: null,
        listTaskId: groupTaskList?.listTaskId,
        description: null,
        // tags: this.formNewTask.controls.tags.value,
        taskIn: null,
        checkListDtoList: [],
        deleteCheckListDtoList: [],
        listAttachmentId: [],
        subTaskDtoList: [],
      };
      const dataResp = await BoardServices.createTask(dataUpdate);

      if (dataResp) {
        setListTask([dataResp, ...listTask]);
        setTotalItem(totalItem + 1);
      }
    } catch (error) {}
  };

  const handleDeleteBoardTask = async (id: string) => {
    const dataResp = await BoardServices.deleteBoardTask(id);
    if (!dataResp) {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Xóa không thành công',
      });
    } else {
      setGroupTaskList(prev => prev.filter(item => item.id !== id));
      setGroupTaskListStore(groupTaskListStore.filter(item => item.id !== id));
      Toast.show({
        type: 'success',
        text1: 'Thông báo',
        text2: 'Xóa thành công',
      });
    }
  };

  const handleAddBoardTask = async (data: {name: string; color: string}) => {
    const body = {
      name: data?.name,
      listTask: {
        id: taskSelectId,
      },
      attr: JSON.stringify({
        color: data?.color,
        order:
          Math.max(
            ...groupTaskListStore?.map(g => JSON.parse(g.attr || '{}')?.order),
          ) + 1,
        type: 'custom',
        status: 'open',
      }),
      type: 'custom',
    };
    const dataResp = await BoardServices.addGroupTask(body);
    if (dataResp) {
      setGroupTaskList(prev => [...prev, dataResp]);
      setGroupTaskListStore([...groupTaskListStore, dataResp]);
      setOpenModal(null);
    } else {
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Thêm không thành công',
      });
    }
  };

  const handleGetName = () => {
    return groupTaskList?.type !== 'custom'
      ? t(`TK.${groupTaskList?.name}`)
      : groupTaskList?.name;
  };
  const handleCopy = async () => {
    try {
      setModalCopy(false);
      const newTask = await Taskservices.copyTemplateTask(
        selectedTask?.id || '',
      );
      setListTask(prev => [newTask, ...prev]);
      setTotalItem(prev => prev + 1);
      Toast.show({
        type: 'success',
        text1: t('CM.noti'),
        text2: 'Copy task thành công',
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Có lỗi xảy ra',
      });
    }
  };
  const handleDelete = async () => {
    try {
      await Taskservices.deleteTaskById(selectedTask?.id || '');
      setListTask(prev => prev.filter(task => task.id !== selectedTask?.id));
      setTotalItem(prev => prev - 1);
      setModalDelete(false);
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Có lỗi xảy ra',
      });
    }
  };
  const validStatuses = groupTaskListStore.map(g => g.id);
  const groupTask: Record<string, ITaskDetail[]> = listTask.reduce(
    (acc, task) => {
      if (!task.status || !validStatuses.includes(task.status)) {
        return acc; // Bỏ qua task không hợp lệ
      }
      if (!acc[task.status]) acc[task.status] = [];
      acc[task.status].push(task);
      return acc;
    },
    {} as Record<string, ITaskDetail[]>,
  );

  const fixedStatusList = ['todo', 'processing', 'approved', 'completed'];

  const statusIdByType: Record<string, string> = {};
  groupTaskListStore.forEach(group => {
    const parsedAttr = JSON.parse(group.attr || '{}');
    if (parsedAttr.type) {
      statusIdByType[parsedAttr.type] = group.id;
    }
  });

  const tableDataGroup = fixedStatusList.map(typeKey => {
    const statusId = statusIdByType[typeKey]; // Lấy ID group theo type
    const tasks = groupTask[statusId] || [];

    const sortedTasks = tasks.sort((a, b) => {
      return (
        new Date(b.createdDate).getTime() - new Date(a.createdDate).getTime()
      );
    });

    const formatDateTime = (dateString: string) => {
      const date = new Date(dateString);
      const pad = (num: number) => num.toString().padStart(2, '0');

      const hours = pad(date.getHours());
      const minutes = pad(date.getMinutes());
      const day = pad(date.getDate());
      const month = pad(date.getMonth() + 1); // tháng tính từ 0
      const year = date.getFullYear();

      return `${day}/${month}/${year} ${hours}:${minutes} `;
    };

    const tableData = sortedTasks.map((task, index) => {
      return {
        'HM.board.table-order': index + 1,
        'HM.board.table-name': task.name,
        'HM.board.table-tag': task.tags?.join(', ') || '_',
        'HM.board.table-created-date': task.createdDate
          ? formatDateTime(task.createdDate)
          : '_',
        'HM.board.table-start-date': task.startDate
          ? formatDateTime(task.startDate)
          : '_',
        'HM.board.table-due-date': task.dueDate
          ? formatDateTime(task.dueDate)
          : '_',
        'HM.board.table-overdue': '_',
        'HM.board.table-assignee':
          task.assignTaskList?.length > 0 ||
          task.assignGroupList?.length > 0 ||
          task.assignOrgList?.length > 0 ? (
            <Pressable
              onPress={() => {
                setOpenModalAvatar('assign');
                setSelectedTask(task);
              }}>
              <RenderListUserAssign
                assignTaskList={task.assignTaskList || []}
                assignGroupList={task.assignGroupList || []}
                assignOrgList={task.assignOrgList || []}
              />
            </Pressable>
          ) : (
            <TextCM style={{fontStyle: 'italic'}}>_</TextCM>
          ),
        'HM.board.table-subtask': (
          <View style={styles.ctnBumberTask}>
            <ProgressBar
              style={styles.ctnProgressbar}
              progress={task.percent}
            />
            <TextCM style={{fontSize: 13}}>{`${Number(
              task.percent * 100,
            ).toFixed(1)}% (${Math.ceil(task.percent * task.numberSubtasks)}/${
              task.numberSubtasks
            })`}</TextCM>
          </View>
        ),
        'HM.board.table-action': (
          <View style={styles.listAction}>
            <TouchableOpacity
              onPress={() => {
                navigation.navigate(NavigationName.TaskDetailScreen, {
                  taskId: task.id,
                  isFromTemplate: true,
                });
              }}>
              <Icon
                name="edit-2-outline"
                width={16}
                height={16}
                fill={'gray'}
              />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => {
                setModalCopy(true);
                setSelectedTask(task);
              }}>
              <Icon name="copy" width={16} height={16} fill={'gray'} />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => {
                setSelectedTask(task);
                setModalDelete(true);
              }}>
              <Icon name="trash-2" width={16} height={16} fill={'gray'} />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => {
                setSelectedTask(task);
                setShareAuthorize(true);
              }}>
              <Icon name="share" width={16} height={16} />
            </TouchableOpacity>
          </View>
        ),
      };
    });

    return {
      status: typeKey,
      tableData,
    };
  });

  return (
    <>
      {viewType === 'table' && (
        <GestureHandlerRootView style={{backgroundColor: '#fff'}}>
          <View
            style={{
              width: width > TYPE_SCREEN.mobile ? width / 2 : width,
              flex: 1,
            }}>
            <View
              style={{
                ...styles.ctn,
                backgroundColor: `${attr?.color}1A`,
                flex: listTask.length > 0 ? 1 : 0,
                borderTopColor: attr?.color,
              }}>
              <View style={styles.ctnFirstHeader}>
                <View style={styles.ctnHeader}>
                  {groupTaskList?.type !== 'add' ? (
                    <>
                      <TextCM style={styles.txtName}>{handleGetName()}</TextCM>
                      <View
                        style={{
                          ...styles.ctnNumbTask,
                          backgroundColor: attr?.color,
                        }}>
                        <TextCM style={styles.txtNumbTask}>{totalItem}</TextCM>
                      </View>
                    </>
                  ) : (
                    <Pressable
                      style={{flex: 1}}
                      onPress={() => setOpenModal('editTask')}>
                      <TextCM style={styles.textAddStatus}>
                        + thêm trạng thái
                      </TextCM>
                    </Pressable>
                  )}
                </View>

                {groupTaskList?.type === 'custom' && (
                  <Pressable
                    onPress={() => handleDeleteBoardTask(groupTaskList?.id)}>
                    <Icon
                      fill={attr?.color}
                      name="close"
                      width={20}
                      height={20}
                    />
                  </Pressable>
                )}
              </View>

              <FlatList
                // containerStyle={{flex: 1}}
                data={listTask}
                refreshControl={
                  <RefreshControl
                    tintColor={'#FCF450'}
                    onRefresh={onRefresh}
                    refreshing={isLoading}
                  />
                }
                contentContainerStyle={{rowGap: 10}}
                onEndReachedThreshold={0.5}
                onEndReached={fetchNextPage}
                showsHorizontalScrollIndicator={false}
                showsVerticalScrollIndicator={false}
                keyExtractor={(item, index) => item.id.toString()}
                // onDragBegin={index => {
                //   console.log(index);
                // }}
                // onDragEnd={({data}) => handleDragData(data)}
                renderItem={({item}) => (
                  <Pressable
                    onPress={() => handleViewDetail(item)}
                    // onLongPress={drag}
                    // disabled={isActive}
                  >
                    <ItemTicket
                      itemTask={item}
                      listTask={listTask}
                      setListTask={setListTask}
                    />
                  </Pressable>
                )}
              />

              {groupTaskList?.type !== 'add' &&
                groupTaskList?.type !== 'completed' && (
                  <Pressable onPress={handleAddtask} style={styles.ctnAddTask}>
                    <Icon
                      fill={Color.Text}
                      name="plus-circle-outline"
                      width={20}
                      height={20}
                    />
                    <TextCM style={styles.txtAddtask}>Thêm công việc</TextCM>
                  </Pressable>
                )}
            </View>
          </View>
        </GestureHandlerRootView>
      )}
      {viewType === 'list' && (
        <>
          <ScrollView style={{paddingHorizontal: 16}}>
            <ListTable tableDataGroup={tableDataGroup} />
          </ScrollView>
        </>
      )}
      {viewType === 'calendar' && (
        <>
          <CalenderView
            listTask={listTask}
            groupTask={groupTaskList}
            setListTask={setListTask}
            taskSelectId={taskSelectId}
          />
        </>
      )}

      <ModalFullScreen
        isVisible={openModal === 'createTask'}
        children={
          <AddTaskScreen
            resourceId={taskSelectId}
            onClose={() => setOpenModal(null)}
            handleSubmitData={handleCreateTask}
          />
        }
      />

      {/* Modal Edit Task */}
      <ModalFullScreen
        isVisible={openModal === 'editTask'}
        children={
          <AddBoard
            onClose={() => setOpenModal(null)}
            handleSubmitData={handleAddBoardTask}
          />
        }
      />
      <ModalFullScreen
        isVisible={openModalAvatar === 'assign'}
        children={
          <ModalSelectUser
            onClose={() => setOpenModalAvatar(null)}
            type="T"
            task={selectedTask ?? undefined}
          />
        }
      />
      <ModalConfirmCM
        type="cancel"
        title={'Xoá mẫu công việc'}
        content={'Bạn có muốn xoá mẫu công việc'}
        onClose={() => setModalDelete(false)}
        isVisible={modalDelete}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleDelete()}
      />
      <ModalConfirmCM
        type="info"
        title={'Nhân bản mẫu công việc'}
        content={'Bạn có chắc chắn muốn nhân bản mẫu công việc?'}
        onClose={() => setModalCopy(false)}
        isVisible={modalCopy}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleCopy()}
      />
      <ModalFullScreen
        isVisible={shareAuthorize}
        children={
          <AuthorityAndShareScreen
            type="T"
            onClose={() => setShareAuthorize(false)}
            resource={(selectedTask || {}) as ITask}
          />
        }
      />
    </>
  );
};
export default TaskDetailItem;
