import {useEffect, useState} from 'react';
import {Pressable, View} from 'react-native';
import TextCM from '../../../../../../components/Text';
import {Agenda} from 'react-native-calendars';
import {ITaskDetail} from '../../helper';
import {DateUtils} from '../../../../../../../utils';
import styles from '../../styles';
import {Icon} from '@ui-kitten/components';
import {Color, NavigationName} from '../../../../../../../constants';
import {useNavigation} from '@react-navigation/native';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import AddTaskScreen from '../add-task';
import {useBoardService} from '../../../../../../../hooks/apiHooks/useAPI';
import {GroupTaskList} from '../../../../../board/store/interface';
import BottomSheetCM from '../../../../../../components/BottomSheet';
import ListActionTaskDetail from '../../../ListActionTaskDetail';

type Props = {
  listTask: ITaskDetail[];
  groupTask?: GroupTaskList | undefined;
  setListTask: (state: ITaskDetail[]) => void;
  taskSelectId: string;
};

type Items = Record<
  string,
  {id: string; name: string; data: string; startDate: string; dueDate: string}[]
>;

const CalenderView = ({
  listTask,
  groupTask,
  setListTask,
  taskSelectId,
}: Props) => {
  const [items, setItems] = useState<Items>({});
  const navigation = useNavigation<any>();
  const stripHtml = (html: string) => html.replace(/<[^>]*>/g, '');
  const [openModal, setOpenModal] = useState(false);
  const [isShowAction, setIsShowAction] = useState(false);
  const [taskSelected, setTaskSelected] = useState<any>(null);

  const BoardServices = useBoardService();

  const handleCreateTask = async (data: any) => {
    try {
      const dataUpdate = {
        ...data,
        status: groupTask?.id,
        id: null,
        listTaskId: groupTask?.listTaskId,
        description: null,
        taskIn: null,
        checkListDtoList: [],
        deleteCheckListDtoList: [],
        listAttachmentId: [],
        subTaskDtoList: [],
      };
      const dataResp = await BoardServices.createTask(dataUpdate);
      if (dataResp) {
        setListTask([dataResp, ...listTask]);
      }
    } catch (error) {
      console.log('Lỗi tạo task:', error);
    }
  };

  useEffect(() => {
    const newItems: Items = listTask.reduce((acc, task) => {
      const rawDate = task.startDate;
      const rawDueDate = task.dueDate;
      const convertDate = DateUtils.convertDateToNextDate(new Date(rawDate));
      const dateKey = convertDate
        ? convertDate.toISOString().split('T')[0]
        : '';
      const startTime = rawDate
        ? DateUtils.formatTimeAMPM(new Date(rawDate))
        : '';
      const dueTime = rawDueDate
        ? DateUtils.formatTimeAMPM(new Date(rawDueDate))
        : '';

      if (!acc[dateKey]) acc[dateKey] = [];

      acc[dateKey].push({
        id: task.id,
        name: task.name,
        data: task.description,
        startDate: startTime,
        dueDate: dueTime,
      });

      return acc;
    }, {} as Items);

    Object.keys(newItems).forEach(dateKey => {
      if (!newItems[dateKey].some(i => i.name === 'add_button')) {
        newItems[dateKey].push({
          name: 'add_button',
          data: '',
          id: new Date().getTime().toString() + dateKey,
          startDate: '',
          dueDate: '',
        });
      }
    });
    setItems(newItems);
  }, [listTask]);

  const handleViewDetail = (item: {
    id: string;
    name: string;
    data: string;
    startDate: string;
    dueDate: string;
  }) => {
    navigation.navigate(NavigationName.TaskDetailScreen, {
      taskId: item.id,
      type: 'task',
    });
  };

  return (
    <View style={{flex: 1}}>
      <Agenda
        items={items}
        renderItem={(item: {
          id: string;
          name: string;
          data: string;
          startDate: string;
          dueDate: string;
        }) => {
          if (item.name === 'add_button') {
            return (
              <Pressable
                style={styles.ctnAddTask}
                onPress={() => setOpenModal(true)}>
                <Icon
                  fill={Color.Text}
                  name="plus-circle-outline"
                  width={20}
                  height={20}
                />
                <TextCM style={styles.txtAddtask}>Thêm công việc</TextCM>
              </Pressable>
            );
          }

          return (
            <View>
              <Pressable
                onPress={() => handleViewDetail(item)}
                style={styles.calendarCtn}>
                <View
                  style={styles.headerCld}>
                  <TextCM>
                    {item.startDate} - {item.dueDate}
                  </TextCM>
                  <Pressable
                    onPress={() => {
                      setTaskSelected(item);
                      setIsShowAction(true);
                    }}>
                    <Icon name="more-horizontal" width={24} height={24} />
                  </Pressable>
                </View>
                <TextCM>{item.name}</TextCM>
                <TextCM>{stripHtml(item.data || '')}</TextCM>
              </Pressable>
            </View>
          );
        }}
        renderEmptyData={() => (
          <Pressable
            style={styles.ctnAddTask}
            onPress={() => setOpenModal(true)}>
            <Icon
              fill={Color.Text}
              name="plus-circle-outline"
              width={20}
              height={20}
            />
            <TextCM style={styles.txtAddtask}>Thêm công việc</TextCM>
          </Pressable>
        )}
      />
      <ModalFullScreen
        isVisible={openModal}
        children={
          <AddTaskScreen
            onClose={() => setOpenModal(false)}
            handleSubmitData={handleCreateTask}
            resourceId={taskSelectId}
          />
        }
      />
      <BottomSheetCM
        title={'Action'}
        isVisible={isShowAction}
        onClose={() => setIsShowAction(false)}
        renderContent={
          <ListActionTaskDetail
            taskSelect={taskSelected}
            onClose={() => setIsShowAction(false)}
            listTask={listTask}
            setListTask={setListTask}
          />
        }
      />
    </View>
  );
};

export default CalenderView;
